import { ChangeDetectorRef, Component, Input } from '@angular/core';
import { VerificacionCredito } from '../../../../models/verificacion.credito.model';
import { Form, FormConditional, GenericFormComponent } from '../../../../shared/generic-form/generic-form.component';
import { VerificacionCreditoService } from '../../../../controllers/verificacion.credito.service';
import { UtilsService } from '../../../../services/utils.service';
import { ActivatedRoute, ActivatedRouteSnapshot } from '@angular/router';
import { FieldTypesService } from '../../../../shared/generic-form/form-field/field-types.service';
import { Credito } from '../../../../models/credito.model';
import { CreditoService } from '../../../../controllers/credito.service';

const FORM_DEF:Form=[
  {
    title:'Datos de Verificacion',
    fields:[
      {
        key:'concepto',
        label:'Concepto',
        options:['DATOS PERSONALES PF','NEGOCIO PF','NEGOCIO PM','REPRESENTANTE LEGAL PM','ACCIONISTAS PM','ACTA CONSTITUTIVA PM', 'AVAL','REFERENCIAS PERSOALES/SOCIOS']
      },
      {
        key:'revision_datos_ingresados',
        label:'Revision de Datos Ingresados',
        options:['SI','NO', 'NO APLICA']
      },
      {
        key:'llamada_telefonica',
        label:'Llamada Telefónica',
        options:['SI','NO', 'NO APLICA']
      },
      {
        key:'visita_domicilio',
        label:'¿Se visitó el domicilio?',
        options:['SI','NO', 'NO APLICA'],
        style:{
          div:'col-12 col-sm p-3'
        }
      },
    ]
  },
  {
    key:'foto_domicilio',
    fileKey:'document',
    label:'Foto Domicilio',
    foreign_key:'id',
    apiUrl:'api/files/verificacion/domicilio/foto/save',
    accept:'.png, .jpeg, .jpg',
    showDownload:true,
  },
  {
    title:'Ubicacion de la visita',
    key:'mapField',
    latitud:{
      key:'latitud_domicilio'
    },
    longitud:{
      key:'longitud_domicilio'
    },
    hidden:true,
  },
  {
    title:'Reportes de verificacion',
    apiUrl:'api/reportes_creditos_verificaciones',
    foreign_key:'verificacion_credito_id',
    baseFields:[
      {
        key:'tipo',
        label:'Tipo de Reporte',
        options:['DOMICILIO NO ENCONTRADO','DATOS INCORRECTOS','TELEFONO NO VALIDO','OTRO'],
        style:{
          div:'col-12 col-sm-6 p-1'
        }
      },
      {
        key:'estado',
        label:'Estado',
        options:['PENDIENTE', 'SOLUCIONADO'],
        style:{
          div:'col-12 col-sm-6 p-1'
        }
      },
      {
        key:'nota',
        label:'Notas:',
        type:'text',
        style:{
          div:'col-12 col-sm p-1'
        }
      },
    ]
  },
]


@Component({
    selector: 'app-form-verificaciones-credito',
    imports: [GenericFormComponent],
    templateUrl: './form-verificaciones-credito.component.html',
    styleUrl: './form-verificaciones-credito.component.css'
})
export class FormVerificacionesCreditoComponent {
  credito?:Credito
  form= FORM_DEF
  @Input() divClass:string='container p-3 rounded bg-light shadow my-1'
  @Input() verificacionCredito?: VerificacionCredito
  conditionals:FormConditional[]=[
    {
      key:'visita_domicilio',
      operator:'!==',
      value:'NO APLICA',
      target:'mapField',
      targetAction:'unhide'
    },
  ]
  readonly:boolean=false

  constructor(
    private utils:UtilsService,
    private route:ActivatedRoute,
    public verificacionCreditoController:VerificacionCreditoService,
    private creditoController:CreditoService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('verificacion_id'))
      if(id){
        this.verificacionCredito= await this.verificacionCreditoController.find(id)
        if(this.verificacionCredito){
          this.credito=await this.creditoController.find(this.verificacionCredito.credito_id)
        }
      }
    })
    this.readonly= !!this.route.snapshot.queryParamMap.get('readonly')
  }

}
